using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using WebApi.Infrastructure.Persistence.Entities;
namespace WebApi.Infrastructure.Persistence.Configurations;
public sealed class CredentialSecurityConfiguration : IEntityTypeConfiguration<EnvironmentSecurityState>,IEntityTypeConfiguration<SecurityOperation>,IEntityTypeConfiguration<SecurityEvent>,IEntityTypeConfiguration<CredentialRevocation>,IEntityTypeConfiguration<SecurityOutboxMessage>,IEntityTypeConfiguration<SecurityOperationTarget>,IEntityTypeConfiguration<GatewaySecurityLease>,IEntityTypeConfiguration<GatewaySecurityLeaseIssuance>,IEntityTypeConfiguration<GatewaySecurityLeaseExpiryObservation>,IEntityTypeConfiguration<SecurityAckRecord>,IEntityTypeConfiguration<SecurityAckVerification>,IEntityTypeConfiguration<SecurityAckRevalidationChallenge>,IEntityTypeConfiguration<SecurityAckAttempt>,IEntityTypeConfiguration<SecurityAckFailureLatest>,IEntityTypeConfiguration<SecurityOperationAlert>,IEntityTypeConfiguration<GatewaySecurityCurrentReceipt>
{
 private static void Columns<T>(EntityTypeBuilder<T> b,string table) where T:class
 {b.ToTable(table);foreach(var p in typeof(T).GetProperties()){var name=System.Text.RegularExpressions.Regex.Replace(p.Name,"([a-z0-9])([A-Z])","$1_$2").ToLowerInvariant();b.Property(p.Name).HasColumnName(name);}}
 private static void Scope<T>(EntityTypeBuilder<T> b) where T:class
 {b.HasOne<EnvironmentRecord>().WithMany().HasForeignKey("EnvironmentId","ProjectId").HasPrincipalKey("Id","ProjectId").OnDelete(DeleteBehavior.Restrict);b.HasOne<Project>().WithMany().HasForeignKey("ProjectId","OrganizationId").HasPrincipalKey("Id","OrganizationId").OnDelete(DeleteBehavior.Restrict);}
 public void Configure(EntityTypeBuilder<EnvironmentSecurityState> b)
 {Columns(b,"environment_security_states");b.HasKey(x=>x.EnvironmentId);b.HasAlternateKey(x=>new{x.EnvironmentId,x.SecurityGeneration});Scope(b);b.Property(x=>x.LeaseSeconds).HasDefaultValue(30);b.Property(x=>x.LeaseRefreshSeconds).HasDefaultValue(5);b.Property(x=>x.MaximumClockSkewSeconds).HasDefaultValue(2);b.ToTable(t=>t.HasCheckConstraint("ck_security_lease_policy","lease_seconds BETWEEN 5 AND 30 AND lease_refresh_seconds BETWEEN 1 AND 15 AND lease_refresh_seconds<=lease_seconds/2 AND maximum_clock_skew_seconds BETWEEN 0 AND 2 AND minimum_snapshot_schema IN ('2.0','2.1','2.2','2.3','2.4')"));b.Property(x=>x.HeadHash).HasMaxLength(64);b.Property(x=>x.MinimumSnapshotSchema).HasMaxLength(24);b.Property(x=>x.Revision).IsConcurrencyToken();b.ToTable(t=>t.HasCheckConstraint("ck_security_state","epoch >= 0 AND revision > 0 AND length(head_hash)=64 AND security_generation <> '00000000-0000-0000-0000-000000000000'::uuid"));}
 public void Configure(EntityTypeBuilder<SecurityOperation> b)
 {Columns(b,"security_operations");b.HasKey(x=>x.Id);b.HasAlternateKey(x=>new{x.Id,x.OrganizationId});b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<UserRecord>().WithMany().HasForeignKey(x=>x.RequestedBy).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationRecord>().WithMany().HasForeignKey(x=>new{x.ApplicationId,x.OrganizationId}).HasPrincipalKey(x=>new{x.Id,x.OrganizationId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationCredential>().WithMany().HasForeignKey(x=>new{x.CredentialId,x.ApplicationId,x.OrganizationId}).HasPrincipalKey(x=>new{x.Id,x.ApplicationId,x.OrganizationId}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.Reason).HasMaxLength(1000);b.Property(x=>x.Kind).HasMaxLength(32);b.HasIndex(x=>x.CredentialId).IsUnique().HasFilter("kind = 'CredentialRevoke'");b.ToTable(t=>t.HasCheckConstraint("ck_security_operation","revision > 0 AND ((kind = 'CredentialRevoke' AND application_id IS NOT NULL AND credential_id IS NOT NULL) OR kind = 'EnvironmentPolicyCutover')"));}
 public void Configure(EntityTypeBuilder<SecurityEvent> b)
 {Columns(b,"security_events");b.HasKey(x=>new{x.EnvironmentId,x.SecurityGeneration,x.Epoch});b.HasAlternateKey(x=>new{x.OperationId,x.EnvironmentId});Scope(b);b.HasOne<EnvironmentSecurityState>().WithMany().HasForeignKey(x=>new{x.EnvironmentId,x.SecurityGeneration}).HasPrincipalKey(x=>new{x.EnvironmentId,x.SecurityGeneration}).OnDelete(DeleteBehavior.Restrict);b.HasOne<SecurityOperation>().WithMany().HasForeignKey(x=>new{x.OperationId,x.OrganizationId}).HasPrincipalKey(x=>new{x.Id,x.OrganizationId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationCredential>().WithMany().HasForeignKey(x=>x.CredentialId).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.EventType).HasMaxLength(32);b.Property(x=>x.PreviousHash).HasMaxLength(64);b.Property(x=>x.EventHash).HasMaxLength(64);b.Property(x=>x.PolicyJson).HasColumnType("jsonb");b.ToTable(t=>t.HasCheckConstraint("ck_security_event","epoch > 0 AND length(previous_hash)=64 AND length(event_hash)=64 AND ((event_type='CredentialRevoked' AND credential_id IS NOT NULL AND policy_json IS NULL) OR (event_type='EnvironmentPolicyChanged' AND credential_id IS NULL AND policy_json IS NOT NULL))"));}
 public void Configure(EntityTypeBuilder<CredentialRevocation> b)
 {Columns(b,"credential_revocations");b.HasKey(x=>new{x.EnvironmentId,x.CredentialId});Scope(b);b.HasOne<ApplicationCredential>().WithMany().HasForeignKey(x=>new{x.CredentialId,x.ApplicationId,x.OrganizationId}).HasPrincipalKey(x=>new{x.Id,x.ApplicationId,x.OrganizationId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<SecurityEvent>().WithMany().HasForeignKey(x=>new{x.EnvironmentId,x.SecurityGeneration,x.Epoch}).OnDelete(DeleteBehavior.Restrict);b.HasOne<SecurityOperation>().WithMany().HasForeignKey(x=>new{x.OperationId,x.OrganizationId}).HasPrincipalKey(x=>new{x.Id,x.OrganizationId}).OnDelete(DeleteBehavior.Restrict);}
 public void Configure(EntityTypeBuilder<SecurityOutboxMessage> b)
 {Columns(b,"security_outbox_messages");b.HasKey(x=>x.Id);b.HasOne<SecurityEvent>().WithMany().HasForeignKey(x=>new{x.EnvironmentId,x.SecurityGeneration,x.Epoch}).OnDelete(DeleteBehavior.Restrict);b.HasOne<SecurityOperation>().WithMany().HasForeignKey(x=>x.OperationId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.EnvironmentId,x.SecurityGeneration,x.Epoch}).IsUnique();b.HasIndex(x=>new{x.ProcessedAt,x.LeaseUntil,x.CreatedAt}).HasFilter("processed_at IS NULL");b.ToTable(t=>t.HasCheckConstraint("ck_security_outbox","epoch > 0 AND attempts >= 0"));}
 public void Configure(EntityTypeBuilder<SecurityOperationTarget> b)
 {Columns(b,"security_operation_targets");b.HasKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid});b.HasAlternateKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid,x.ChallengeNonce});b.HasOne<SecurityEvent>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId}).HasPrincipalKey(x=>new{x.OperationId,x.EnvironmentId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<GatewayNode>().WithMany().HasForeignKey(x=>new{x.NodeId,x.EnvironmentId}).HasPrincipalKey(x=>new{x.Id,x.EnvironmentId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<SecurityOperationTarget>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.SupersededByInstanceGuid}).HasPrincipalKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.TargetState).HasMaxLength(32);b.HasIndex(x=>x.ChallengeNonce).IsUnique();b.ToTable(t=>t.HasCheckConstraint("ck_security_target","target_state IN ('Pending','Applied','SafeSuperseded','AwaitingRegistration') AND ((instance_guid = '00000000-0000-0000-0000-000000000000'::uuid AND target_state IN ('AwaitingRegistration','SafeSuperseded')) OR (instance_guid<>'00000000-0000-0000-0000-000000000000'::uuid AND target_state<>'AwaitingRegistration'))"));}
 public void Configure(EntityTypeBuilder<GatewaySecurityLease> b)
 {Columns(b,"gateway_security_leases");b.HasKey(x=>new{x.NodeId,x.InstanceId});b.HasAlternateKey(x=>new{x.NodeId,x.InstanceId,x.EnvironmentId,x.ProjectId,x.OrganizationId,x.SecurityGeneration});Scope(b);b.HasOne<GatewayNode>().WithMany().HasForeignKey(x=>new{x.NodeId,x.EnvironmentId}).HasPrincipalKey(x=>new{x.Id,x.EnvironmentId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<EnvironmentSecurityState>().WithMany().HasForeignKey(x=>new{x.EnvironmentId,x.SecurityGeneration}).HasPrincipalKey(x=>new{x.EnvironmentId,x.SecurityGeneration}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.CheckpointHash).HasMaxLength(64);b.Property(x=>x.SigningKeyId).HasMaxLength(64);b.Property(x=>x.Revision).IsConcurrencyToken();b.HasIndex(x=>x.LeaseId).IsUnique();b.HasIndex(x=>new{x.EnvironmentId,x.FreshUntil});b.ToTable(t=>t.HasCheckConstraint("ck_gateway_security_lease","epoch>=0 AND revision>0 AND lease_seconds BETWEEN 5 AND 30 AND last_issued_lease_until>=fresh_until AND fresh_until>issued_at AND fresh_until<=issued_at+make_interval(secs=>lease_seconds) AND instance_id<>'00000000-0000-0000-0000-000000000000'::uuid AND checkpoint_hash ~ '^[a-f0-9]{64}$'"));}
 public void Configure(EntityTypeBuilder<GatewaySecurityLeaseIssuance> b)
 {Columns(b,"gateway_security_lease_issuances");b.HasKey(x=>x.LeaseId);b.HasIndex(x=>x.IssuedAt);b.HasAlternateKey(x=>new{x.LeaseId,x.NodeId,x.InstanceId,x.EnvironmentId,x.SecurityGeneration,x.Epoch,x.CheckpointHash});Scope(b);b.HasOne<GatewaySecurityLease>().WithMany().HasForeignKey(x=>new{x.NodeId,x.InstanceId,x.EnvironmentId,x.ProjectId,x.OrganizationId,x.SecurityGeneration}).HasPrincipalKey(x=>new{x.NodeId,x.InstanceId,x.EnvironmentId,x.ProjectId,x.OrganizationId,x.SecurityGeneration}).OnDelete(DeleteBehavior.Restrict);b.HasOne<EnvironmentSecurityState>().WithMany().HasForeignKey(x=>new{x.EnvironmentId,x.SecurityGeneration}).HasPrincipalKey(x=>new{x.EnvironmentId,x.SecurityGeneration}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.CheckpointHash).HasMaxLength(64);b.Property(x=>x.PayloadHash).HasMaxLength(64);b.Property(x=>x.SigningKeyId).HasMaxLength(64);b.ToTable(t=>t.HasCheckConstraint("ck_security_lease_issuance","lease_id<>'00000000-0000-0000-0000-000000000000'::uuid AND instance_id<>'00000000-0000-0000-0000-000000000000'::uuid AND epoch>=0 AND fresh_until>issued_at AND fresh_until<=issued_at+interval '30 seconds' AND checkpoint_hash ~ '^[a-f0-9]{64}$' AND payload_hash ~ '^[a-f0-9]{64}$'"));}
 public void Configure(EntityTypeBuilder<GatewaySecurityLeaseExpiryObservation> b)
 {Columns(b,"gateway_security_lease_expiry_observations");b.HasKey(x=>x.LeaseId);b.HasIndex(x=>x.ObservedAt);b.HasOne<GatewaySecurityLeaseIssuance>().WithMany().HasForeignKey(x=>x.LeaseId).OnDelete(DeleteBehavior.Restrict);}
 public void Configure(EntityTypeBuilder<GatewaySecurityCurrentReceipt> b)
 {Columns(b,"gateway_security_current_receipts");b.HasKey(x=>new{x.NodeId,x.InstanceId});b.HasIndex(x=>x.ReceivedAt);Scope(b);b.HasOne<GatewayNode>().WithMany().HasForeignKey(x=>new{x.NodeId,x.EnvironmentId}).HasPrincipalKey(x=>new{x.Id,x.EnvironmentId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<GatewaySecurityLease>().WithMany().HasForeignKey(x=>new{x.NodeId,x.InstanceId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<EnvironmentSecurityState>().WithMany().HasForeignKey(x=>new{x.EnvironmentId,x.SecurityGeneration}).HasPrincipalKey(x=>new{x.EnvironmentId,x.SecurityGeneration}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.CheckpointHash).HasMaxLength(64);b.Property(x=>x.HeadHash).HasMaxLength(64);b.HasIndex(x=>x.LeaseId).IsUnique();b.ToTable(t=>t.HasCheckConstraint("ck_current_security_receipt","epoch>=0 AND checkpoint_hash ~ '^[a-f0-9]{64}$' AND head_hash ~ '^[a-f0-9]{64}$' AND fresh_until>received_at AND lease_id<>'00000000-0000-0000-0000-000000000000'::uuid"));}
 public void Configure(EntityTypeBuilder<SecurityAckRecord> b)
 {Columns(b,"security_acks");b.HasKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid});b.HasOne<SecurityOperationTarget>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.CheckpointHash).HasMaxLength(64);b.Property(x=>x.ErrorCode).HasMaxLength(64);b.ToTable(t=>t.HasCheckConstraint("ck_security_ack","epoch>0 AND checkpoint_hash ~ '^[a-f0-9]{64}$' AND success AND durable AND admission_enforced AND error_code IS NULL AND challenge_nonce<>'00000000-0000-0000-0000-000000000000'::uuid"));}
 public void Configure(EntityTypeBuilder<SecurityAckVerification> b)
 {Columns(b,"security_ack_verifications");b.HasKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid});b.HasIndex(x=>x.ReceivedAt);b.HasOne<SecurityAckRecord>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid}).OnDelete(DeleteBehavior.Restrict);b.HasOne<SecurityOperationTarget>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid,x.ChallengeNonce}).HasPrincipalKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid,x.ChallengeNonce}).OnDelete(DeleteBehavior.Restrict);b.HasOne<GatewaySecurityLeaseIssuance>().WithMany().HasForeignKey(x=>new{x.LeaseId,x.NodeId,x.InstanceGuid,x.EnvironmentId,x.SecurityGeneration,x.Epoch,x.CheckpointHash}).HasPrincipalKey(x=>new{x.LeaseId,x.NodeId,x.InstanceId,x.EnvironmentId,x.SecurityGeneration,x.Epoch,x.CheckpointHash}).OnDelete(DeleteBehavior.Restrict);b.HasOne<SecurityAckRevalidationChallenge>().WithMany().HasForeignKey(x=>x.RevalidationNonce).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.CheckpointHash).HasMaxLength(64);b.ToTable(t=>t.HasCheckConstraint("ck_security_ack_verification","epoch>0 AND checkpoint_hash ~ '^[a-f0-9]{64}$' AND challenge_nonce<>'00000000-0000-0000-0000-000000000000'::uuid AND lease_id<>'00000000-0000-0000-0000-000000000000'::uuid"));}
 public void Configure(EntityTypeBuilder<SecurityAckRevalidationChallenge> b)
 {Columns(b,"security_ack_revalidation_challenges");b.HasKey(x=>x.Nonce);b.HasIndex(x=>x.CreatedAt);b.HasOne<SecurityOperationTarget>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid,x.ExpiresAt});b.ToTable(t=>t.HasCheckConstraint("ck_security_ack_revalidation_challenge","nonce<>'00000000-0000-0000-0000-000000000000'::uuid AND instance_guid<>'00000000-0000-0000-0000-000000000000'::uuid AND expires_at>created_at AND expires_at<=created_at+interval '30 seconds'"));}
 public void Configure(EntityTypeBuilder<SecurityAckAttempt> b)
 {Columns(b,"security_ack_attempts");b.HasKey(x=>x.Id);b.HasOne<SecurityOperationTarget>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.ErrorCode).HasMaxLength(64);b.Property(x=>x.RequestHash).HasMaxLength(64);b.HasIndex(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid,x.RequestHash}).IsUnique();b.ToTable(t=>t.HasCheckConstraint("ck_security_ack_attempt","request_hash ~ '^[a-f0-9]{64}$' AND error_code IN ('security_lkg_write_denied','security_material_invalid','security_generation_recovery_required','security_state_unavailable','security_full_checkpoint_required','security_epoch_conflict','security_tombstone_regression') AND challenge_nonce<>'00000000-0000-0000-0000-000000000000'::uuid"));}
 public void Configure(EntityTypeBuilder<SecurityAckFailureLatest> b)
 {Columns(b,"security_ack_failure_latest");b.HasKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid});b.HasOne<SecurityOperationTarget>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId,x.NodeId,x.InstanceGuid}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.ErrorCode).HasMaxLength(64);b.Property(x=>x.ObservationCount).IsConcurrencyToken();b.ToTable(t=>t.HasCheckConstraint("ck_security_ack_failure_latest","reported_nonce<>'00000000-0000-0000-0000-000000000000'::uuid AND latest_sequence>0 AND observation_count>0 AND error_code IN ('security_lkg_write_denied','security_material_invalid','security_generation_recovery_required','security_state_unavailable','security_full_checkpoint_required','security_epoch_conflict','security_tombstone_regression')"));}
 public void Configure(EntityTypeBuilder<SecurityOperationAlert> b)
 {Columns(b,"security_operation_alerts");b.HasKey(x=>new{x.OperationId,x.EnvironmentId,x.ThresholdSeconds});b.HasOne<SecurityEvent>().WithMany().HasForeignKey(x=>new{x.OperationId,x.EnvironmentId}).HasPrincipalKey(x=>new{x.OperationId,x.EnvironmentId}).OnDelete(DeleteBehavior.Restrict);b.Property(x=>x.Severity).HasMaxLength(16);b.Property(x=>x.OperationStatus).HasMaxLength(32);b.HasIndex(x=>x.ObservedAt);b.ToTable(t=>t.HasCheckConstraint("ck_security_operation_alert","threshold_seconds BETWEEN 1 AND 86400 AND pending_targets>=0 AND severity IN ('Warning','Escalation') AND operation_status IN ('Unconfirmed','Partial')"));}
}
